-- A command's output: here just the host name.
local host = vim.trim(dbdash.system("hostname").stdout)

-- Data computed in Lua; dbdash.query() could read it from a database instead.
local rows = {}
for i = {{ args.days }} - 1, 0, -1 do            -- template: the value is written into the code
  local t = os.time() - i * 86400
  local load = args.base                    -- args: the value as a Lua number
{% if args.wave %}
  load = load + math.floor(30 * math.sin(i / 2))
{% endif %}
  rows[#rows + 1] = { os.date("%m-%d", t), load, host, i == 0 and dbdash.null or i }
  dbdash.checkpoint()                       -- let the editor run during long loops
end
-- dbdash.null is NULL inside a row (nil would end a Lua list early).
return { columns = { "day", "load", "host", "days_ago" }, rows = rows }
